IG$.sheetViewer = $s.extend(IG$.v$pnl, {
	autofit: true,
	move: false,
	header: false,
	init_f: function() {
		var me = this,
			sheet = me.body ? me.body.dom : null,
			// w = sheet ? me.getWidth() : 0,
			// h = sheet ? me.getHeight() : 0,
			canvas = null,
			i,
			mgrid, gridview;
					
		$(sheet).empty();
		
		gridview = me._gridview = new IG$.olapReportView(me.uid, canvas, sheet, 10);
		gridview.reportoption = me.reportoption;
		gridview.sheetoption = me.sheetoption;
		gridview.sheetobj = me.sheetobj;
		
		mgrid = gridview._mgrid;
		mgrid.sheetoption = me.sheetoption;
		mgrid.sheetobj = me.sheetobj;
		
		mgrid.ctx.bind({
			selectionchanged: function() {
				if (mgrid.selectedItems.length > 1)
				{
					me.fireEvent("drillreport", me);
				}
			},
			itemclick: function(event, renderer) {
				me.fireEvent("itemclick", me, renderer);
			},
			itemdblclick: function(event, renderer) {
				me.fireEvent("itemdblclick", me, renderer);
			},
			menu: function(event, el) {
				me.fireEvent("menu", me, el);
			},
			pivotchanged: function(event) {
				me.fireEvent("pivotchanged", me);
			},
			scroll_request: function(event, row) {
				me.fireEvent("scroll_request", me, row);
			},
			hierarchy: function(event, cell) {
				me.fireEvent("hierarchy", me, cell);
			}
		});
	},
	initCustomControl: function() {
		this.gridcontainer = [];
	},
	
	applyReportResult: function(mresults, olapset, reportoption, sheetoption, ispageview) {
		var me = this,
			sheet = me.body ? me.body.dom : null,
			w = sheet ? me.getWidth() : 0,
			h = sheet ? me.getHeight() : 0,
			// canvas = null,
			// browser = window.bowser,
			i,
			mgrid, gridview,
			_is_sc,
			_hcell;
			
		me.mresults = mresults;
		me.olapset = olapset;
		me.reportoption = reportoption;
		me.sheetoption = sheetoption;
		
		if (!sheet)
			return;
		
		_is_sc = mresults ? mresults._is_sc : false;
		_hcell = mresults ? mresults._hcell : null;
		
//		if (browser.msie && w > 0 && h > 0)
//		{
//			sheet[0].style.width = w + "px";
//			sheet[0].style.height = h + "px";
//		}
		
		var cresult;
		
		if (me.mresults.results.length > 1)
		{
			cresult = me.mresults.results[0];
			
			var rs = me.mresults.results,
				nrows = 0,
				ncols = 0,
				colfix = 0,
				rowfix = 0,
				j, ccode, cvalue, clusterrow;
				
			for (i=0; i < rs.length; i++)
			{
				ccode = rs[i].clustercode.join(" ");
				cvalue = rs[i].clustervalue.join(" ");
				
				if (i == 0)
				{
					rowfix = rs[i].rowfix;
					nrows += rowfix;
					ncols = rs[i].colcnt;
					colfix = rs[i].colfix;
					cresult.styles = rs[i].styles;
				}
				else
				{
					nrows += rs[i].rowcnt - rs[i].rowfix + 1;
				}
				
				clusterrow = [];
				
				for (j=0; j < ncols; j++)
				{
					clusterrow.push({
						text: (j<colfix) ? " " : cvalue || ccode, 
						mrow:0, 
						mcol:ncols-1, 
						merged: (j==0 || j==colfix) ? 2 : 4, 
						stylename: "cluster_data", 
						chart:null,
						position: -1,
						code: null,
						value: null,
						index: -1
					})
				}
				
				if (i == 0)
				{
					cresult._tabledata.splice(rowfix, 0, clusterrow);
				}
				else
				{
					cresult._tabledata.push(clusterrow);
					
					for (j= rs[i].rowfix; j < rs[i].rowcnt; j++)
					{
						cresult._tabledata.push(rs[i]._tabledata[j]);
					}
				}
			}
			
			cresult.rows = nrows;
			cresult.cols = ncols;
			cresult.colfix = colfix;
			cresult.rowfix = rowfix;
		}
		else
		{
			cresult = me.mresults.results[0];
		}

		gridview = me._gridview;
		mgrid = gridview._mgrid;
		
		gridview.width = (w > 0 ? w : gridview.width);
		gridview.height = (h > 0 ? h : gridview.height);

		
		if (me.mresults)
		{
			gridview.jobid = me.mresults.jobid;
			
			if (!_hcell)
			{
				gridview.mresult = cresult;
			}
			
			gridview.reportoption = me.reportoption;
			gridview.sheetoption = me.sheetoption;
			
			mgrid.sheetoption = me.sheetoption;
			
			gridview.drawOlapResult(ispageview, _is_sc, _hcell, cresult);
		}
	},
	CLS: {
		resize: function(w, h) {
			this.setPanelSize(w, h);
		},
		
		afterrender: function(ui) {
			ui.init_f();
		}
	},
	setPanelSize: function(w, h) {
		// console.log("setPanelSize", w, h);
		var me = this,
			_mgrid = me._gridview ? me._gridview._mgrid : null;
		
		_mgrid && _mgrid.resize(w, h)
	},
	
	getDrillXML: function(dobj) {
		var me = this,
			sel = me._gridview._selectedCells(),
			mgrid = me._gridview._mgrid,
			mresult = me._gridview.mresult,
			sop = me.sheetoption,
			model = sop.model,
			showlnum = model.showlnum,
			dinfo = {},
			cell, ocell, cellparent,
			row,
			i, j,
			s1, s2,
			fcol, frow, fmea,
			br = 0,
			bdobj = 0,
			fcnt = 0,
			fitem, fitems,
			findata,
			ditem;
		
		dinfo = {
			ftype: "group",
			conjunction: "AND",
			children: []
		};
		
		if (model.filter)
		{
			dinfo.children.push(model.filter);
		}
		
		if (model.aux_filter)
		{
			$.each(model.aux_filter, function(k, af) {
				dinfo.children.push(af);
			});
		}
			
		if (sel && sel.length > 0)
		{
			if (model.rows.length == 1 && model.cols.length == 0 && (typeof mgrid.treecol == "undefined" || mgrid.treeCol < 0))
			{
				findata = {
					ftype: "group",
					children: [
						{
							ftype: "condition",
							operator: "IN",
							fields: [
								{
									name: model.rows[0].name,
									uid: model.rows[0].uid,
									type: model.rows[0].type
								}
							],
							values: []
						}
					]
				};
				
				dinfo.children.push(findata);
			}
			
			fitems = {
				ftype: "group",
				conjunction: "AND",
				children: []
			};
			
			for (i=0; i < sel.length; i++)
			{
				cell = sel[i];
				
				if (dobj && dobj.titem.enabled) 
				{
					bdobj = 0;
					
					if (cell.position == 1 && model.rows[cell.index] && dobj.titem.item_map[model.rows[cell.index].uid])
					{
						bdobj = 1;
					}
					else if(cell.position == 3 && model.measures && model.measures[cell.index] && dobj.titem.item_map[model.measures[cell.index].uid])
					{
						bdobj = 1;
					}
					else if (cell.position == 2 && model.cols[cell.index] && dobj.titem.item_map[model.cols[cell.index].uid])
					{
						bdobj = 1;
					}
					
					if (bdobj == 0)
					{
						continue;
					}
				}
				
				if (cell.title == 1)
				{
					fcnt++;
					continue;
				}
				
				fcnt++;
				
				fitem = {
					ftype: "group",
					conjunction: "AND",
					children: []
				};
				
				if (mgrid.treeCol > -1)
				{
					row = mgrid.treeData[cell.dr];
					cellparent = row[mgrid.treeCol];
					if (cellparent)
					{
						while (cellparent)
						{
							ocell = cellparent;
							
							if (ocell.position == 1 && model.rows[ocell.index])
							{
								ditem = model.rows[ocell.index];
								
								if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length && !dobj.tparams.item_map[ditem.uid])
								{
									// do nothing
								}
								else
								{
									frow = {
										ftype: "condition",
										operator: "EQ",
										fields: [
											{
												name: ditem.name,
												uid: ditem.uid,
												type: ditem.itemtype
											}
										],
										values: [
											{
												code: ocell.code,
												value: ocell.value
											}
										]
									};
									
									fitem.children.push(frow);
								}
							}
							else if(ocell.position == 3 && model.measures && model.measures[ocell.index])
							{
								ditem = model.measures[ocell.index];
								
								if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length && dobj.tparams.item_map[ditem.uid])
								{
									br = 1;
									fmea = {
										ftype: "measure",
										fields: [
											{
												name: ditem.name,
												uid: ditem.uid,
												type: ditem.itemtype
											}
										]
									};
									fitem.children.push(fmea);
								}
							}
							
							cellparent = ocell.parent;
						}
					}
					else
					{
						ocell = row[mgrid.treeCol];
						
						if (ocell.position == 1 && model.rows[ocell.index])
						{
							ditem = model.rows[ocell.index];
							
							if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length && !dobj.tparams.item_map[ditem.uid])
							{
								// do nothing
							}
							else
							{
								frow = {
									ftype: "condition",
									operator: "EQ",
									fields: [
										{
											name: ditem.name,
											uid: ditem.uid,
											type: ditem.itemtype
										}
									],
									values: [
										{
											code: ocell.code,
											value: ocell.value
										}
									]
								};
	
								fitem.children.push(frow);
							}
						}
						else if(ocell.position == 3 && model.measures && model.measures[ocell.index])
						{
							ditem = model.measures[ocell.index];
							
							if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length)
							{
								if (dobj.tparams.item_map[ditem.uid])
								{
									br = 1;
									fmea = {
										ftype: "measure",
										fields: [
											{
												name: ditem.name,
												uid: ditem.uid,
												type: ditem.itemtype
											}
										]
									};
									dinfo.children.push(fmea);
								}
							}
						}
					}
					
					if (!br && model.measures && model.measures.length == 1 && cell.c >= mresult.colfix && cell.r >= mresult.rowfix)
					{
						ditem = model.measures[0];
						
						if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length)
						{
							if (dobj.tparams.item_map[ditem.uid])
							{
								br = 1;
								fmea = {
									ftype: "measure",
									fields: [
										{
											name: ditem.name,
											uid: ditem.uid,
											type: ditem.itemtype
										}
									]
								};
								fitem.children.push(fmea);
							}
						}
					}
				}
				else
				{
					row = mresult._tabledata[cell.r];
					s1 = (showlnum ? 1 : 0);
					s2 = mresult.colfix + (showlnum ? 1 : 0);
					br = 0;
					
					if ((!dobj || (dobj && !dobj.tparams.enabled)) && cell.c < mresult.colfix)
					{
						if (dobj && dobj._dall)
						{
							
						}
						else
						{
							s1 = cell.c;
							s2 = cell.c+1;
						}
					}
					
					for (j=s1; j < s2; j++)
					{
						ocell = row[j];
						
						if (ocell.position == 1 && model.rows[ocell.index])
						{
							ditem = model.rows[ocell.index];
							
							if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length)
							{
								if (!dobj.tparams.item_map[ditem.uid])
									continue;
							}
							
							if (findata)
							{
								findata.children[0].values.push({
									code: ocell.code,
									value: ocell.value
								});
							}
							else
							{
								frow = {
									ftype: "condition",
									operator: "EQ",
									fields: [
										{
											name: ditem.name,
											uid: ditem.uid,
											type: ditem.type
										}
									],
									values: [
										{
											code: ocell.code,
											value: ocell.value
										}
									]
								};
																
								fitem.children.push(frow);
							}
						}
						else if(ocell.position == 3 && model.measures && model.measures[ocell.index])
						{
							ditem = model.measures[ocell.index];
							
							if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length)
							{
								if (dobj.tparams.item_map[ditem.uid])
								{
									br = 1;
									fmea = {
										ftype: "measure",
										fields: [
											{
												name: ditem.name,
												uid: ditem.uid,
												type: ditem.itemtype
											}
										]
									};
									fitem.children.push(fmea);
								}
							}
						}
					}

					if (model.dataquerymode == "M_DATA")
					{
						ocell = row[cell.c];
						if (ocell.position == 1 && model.rows && model.rows[ocell.index])
						{
							ditem = model.rows[ocell.index];

							if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length)
							{
								if (!dobj.tparams.item_map[ditem.uid])
									continue;
							}

							br = 1;
							fcol = {
								ftype: "condition",
								operator: "EQ",
								fields: [
									{
										name: ditem.name,
										uid: ditem.uid,
										type: ditem.type
									}
								],
								values: [
									{
										code: ocell.code,
										value: ocell.value
									}
								]
							}
							
							fitem.children.push(fcol);
						}
					}
					else
					{
						for (j=0; j < mresult.rowfix; j++)
						{
							ocell = mresult._tabledata[j][cell.c];
							if (ocell.position == 2 && model.cols[ocell.index])
							{
								ditem = model.cols[ocell.index];
								
								if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length)
								{
									if (!dobj.tparams.item_map[ditem.uid])
										continue;
								}
								
								fcol = {
									ftype: "condition",
									operator: "EQ",
									fields: [
										{
											name: ditem.name,
											uid: ditem.uid,
											type: ditem.type
										}
									],
									values: [
										{
											code: ocell.code,
											value: ocell.value
										}
									]
								}
								
								fitem.children.push(fcol);
							}
							else if(ocell.position == 3 && model.measures && model.measures[ocell.index])
							{
								ditem = model.measures[ocell.index];
								
								if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length)
								{
									if (dobj.tparams.item_map[ditem.uid])
									{
										br = 1;
										fmea = {
											ftype: "measure",
											fields: [
												{
													name: ditem.name,
													uid: ditem.uid,
													type: ditem.itemtype
												}
											]
										};
										fitem.children.push(fmea);
									}
								}
							}
						}
					}
					
					if (!br&& model.measures && model.measures.length == 1 && cell.c >= mresult.colfix && cell.r >= mresult.rowfix)
					{
						ditem = model.measures[0];
						
						if (dobj && dobj.tparams && dobj.tparams.enabled && dobj.tparams.items.length)
						{
							if (dobj.tparams.item_map[ditem.uid])
							{
								fmea = {
									ftype: "measure",
									fields: [
										{
											name: ditem.name,
											uid: ditem.uid,
											type: ditem.itemtype
										}
									]
								};
								fitem.children.push(fmea);
							}
						}
					}
				}
				
				if (!findata)
				{
					fitem.conjunction = "OR";
					fitems.children.push(fitem);
				}
			}
			
			dinfo.children.push(fitems);
		}
		
		return (fcnt > 0 ? dinfo : null);
	},
	
	getSelection: function() {
		var me = this,
			sel = me._gridview._selectedCells();
		return sel;
	},
	
	getExportData: function(option, callback) {
		var me = this,
			r = null,
			_parser = me._gridview.mresult,
			_delim = (_parser ? _parser.delim : null);
						
		if (!_parser)
		{
			callback.execute(r);
			return r;
		}
		
		r = {
			jobid: me._gridview.jobid,
			cols: _parser.cols,
			rows: _parser.rows,
			delimiter: _delim,
			fixedrow: _parser.rowfix
		};
		
		callback.execute(r);
	},
	
	applyOptions: function(rop, sop) {
		var me = this;
		
		if (rop && sop)
		{
			me.reportoption = rop;
			me.sheetoption = sop;
		}
		
		me._gridview.applyOptions(me.reportoption, me.sheetoption);
	},
	
	initComponent: function() {
		var me = this;
		
		me.on("resize", function(p, w, h) {
			me.CLS.resize.call(me, w, h);
		});
		
		me.on("afterrender", function(ui) {
			me.CLS.afterrender.call(me, ui);
		});
		
		IG$.sheetViewer.superclass.initComponent.call(this);
	}
});
