IG$.cVis.forcelayout = $s.extend(IG$.cVis.protovis, {
	subtype: "forcelayout",
	draw_protovis: function(mresult) {
		var i,
			j,
			me = this,
			mcr = me.sheetoption ? me.sheetoption.model.chart_option : null,
			data = mresult._tabledata,
			fc = mresult.colfix,
			fr = mresult.rowfix,
			tc = (data.length > 0) ? data[0].length : 0,
			title,
			fields = [],
			matrixdata = [],
			row,
			tn,
			relationgroups = mcr.relationgroups;
	
		mcr.settings = mcr.settings || {};
	
		var jdom = $(me.container),
			w = IG$.j$ext._w(jdom),
			h = IG$.j$ext._h(jdom),
			sep = me.getSep();
	
		var me = this,
			cop = me.chart_option;
	
		me.vismargin = {left: 0, right: 0, top: 0, bottom: 0};
		w -= me.vismargin.left + me.vismargin.right;
		h -= me.vismargin.top + me.vismargin.bottom;
	
		var colors = pv.Colors.category19(),
			rel_range1 = (cop.rel_range1 == IG$.UNDEFINED || cop.rel_range1 == null) ? -1 : cop.rel_range1,
			rel_range2 = (cop.rel_range2 == IG$.UNDEFINED || cop.rel_range2 == null) ? 1 : cop.rel_range2;
	
		var miserables = me.getRelData(mresult, 2, true, relationgroups, {s: rel_range1, t: rel_range2});
	
		me.vis = new pv.Panel()
			.canvas(me.container)
			.width(w)
			.height(h)
			.fillStyle("white")
			.event("mousedown", pv.Behavior.pan())
			.event("mousewheel", pv.Behavior.zoom());
	
		var force = me.vis.add(pv.Layout.Force)
			.nodes(miserables.nodes)
			.links(miserables.links)
			.chargeConstant(-9000);
	
		force.link.add(pv.Line);
	
		force.node.add(pv.Dot)
			.size(function(d) {return (d.linkDegree + 4) * Math.pow(this.scale, -1.5)})
			.fillStyle(function(d) {return d.fix ? "brown" : colors(d.group)})
			.strokeStyle(function() {return this.fillStyle().darker()})
			.lineWidth(1)
			.title(function(d) {return d.nodeName})
			.event("mousedown", pv.Behavior.drag())
			.event("drag", force);
	
		me.vis.render();
	}
});