IG$.aboutApp = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	
	layout: 'fit',
	
	closable: false,
	resizable:false,
	
	width: 500,
	height: 400,
	
	initComponent : function() {
		this.title = IRm$.r1('I_ABOUT', "amplixbi");
		
		$s.apply(this, {
			items: [
				{
					html: '<div class="igc-about-bg"></div>'
						+ '<table width="479" border="0" cellpadding="0" cellspacing="0">'
						+ '<tr>'
						+ '<td width="69" align="left">&nbsp;</td>'
						+ '<td width="410"><div align="right"><span class="about_style6">'
						+ 'Build Id: ' + ((ig$.appInfo.apprelease || "---") + ", web : " + (ig$.appInfo.web_revision || "---")) + '<br/>'
						+ 'Licensed to: ' + ((ig$.appInfo.licensed || "xxx"))
						+ '</span></div></td>'
						+ '</tr>'
						+ '</table>'
						+ '<table width="494" border="0" cellpadding="0" cellspacing="0">'
						+ '<tr>'
						+ '<td width="78">&nbsp;</td>'
						+ '<td width="416" valign="top"><div align="left">'
						+ '<p class="about_style2"> Copyright &copy; 2005-' + ig$.appInfo.date.substring(0, 4) + '<br/>'

						+ 'ALL RIGHTS RESERVED. <br />'
						+ 'amplixbi.com. Confidential Information</p>'
						+ '<p class="about_style1"><span class="about_style4">' + IRm$.r1('L_CONTACT_HELP') + '</span>'
						+ '&nbsp;&nbsp;<a href="http://www.amplixbi.com" target="_new">amplixbi.com</a></p>'
						+ '</div></td>'
						+ '</tr>'
						+ '</table>'

						+ '<p>&nbsp;</p>'
						+ '<p align="left" class="about_style1">&nbsp;</p>'
				}
			],
			
			buttons:[
				{
					text: IRm$.r1('B_CLOSE'),
					handler: function() {
						var me = this;
						me.callback && me.callback.execute();
						me.close();
					},
					scope: this
				}
			]
		});
		
		IG$.aboutApp.superclass.initComponent.apply(this, arguments);
	}
});