IG$.cVis.matrix = $s.extend(IG$.cVis.protovis, {
	subtype: "matrix",

	updatedisplay: function(w, h) {
		var me = this;
		
		if(me.qavis)
		{
			me.qavis.updateDispList.call(me.qavis);
		}
	},

	draw_protovis: function(mresult) {
		var i,
			j,
			data = mresult._tabledata,
			fc = mresult.colfix,
			fr = mresult.rowfix,
			title,
			fields = [],
			matrixdata = [],
			row,
			tn,
			me = this,
			cop = me.chart_option,
			mcr = me.sheetoption.model.chart_option,
			sep = (mcr ? mcr.xaxissep : null) || ig$.chart_separator || IG$._separator;
			
		sep = sep == "nl" ? "\n" : sep;
	
		me.drawmode = "qavis";
	
		for (i=fc; i < data[0].length; i++)
		{
			title = "";
	
			for (j=0; j < fr; j++)
			{
				title = (j==0 ? data[j][i].text : title + sep + data[j][i].text);
			}
			fields.push(title);
		}
	
		for (i=fr; i < data.length; i++)
		{
			row = [];
			for (j=fc; j < data[i].length; j++)
			{
				tn = Number(data[i][j].code);
				row.push(tn);
			}
			matrixdata.push(row);
		}
	
		me.qavis = new IG$.ComparisonMatrix(me.container, {
			cr1: cop.comp_range0,
			cr2: cop.comp_range1
		});
		me.qavis.dataSet = matrixdata;
		me.qavis.fields = fields;
		me.qavis.commitProp();
	}
});