IG$.statistics = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: {
		type: 'fit',
		align: 'stretch'
	},
	
	closable: false,
	resizable:false,
	width: 500,
	height: 440,

	_reqstat: function() {
		var me = this,
			req = new IG$._rpc$(),
			report = me.report,
			activeview = me.activeview;
			
		req.init(me, 
			{
				ack: "olapservice",
				payload: {
					uid: report.uid, 
					option: "statistics",
					active: "" + activeview.sheetindex,
					jobid: activeview.jobid
				},
				mbody: {}
			}, me, function(jdoc) {
				me._init(jdoc);
			});
		req.send();
	},

	_init: function(jdoc) {
		var panel = this,
			mainpanel = panel.down("[name=mainpanel]"),
			el = $(mainpanel.el.dom),
			stat,
			dv, tb, tr, td, title,
			i, j, k, col,
			tdata;
		
		el.empty();
		el.css({"overflow-y": "scroll"});
		
		dv = $("<div class='idv-br-stable'></div>").appendTo(el);
		
		if (jdoc)
		{
			stat = jdoc.statistics;
			
			for (j=0; j < stat.length; j++)
			{
				if (!stat[j])
					continue;
				
				title = "";
				col = stat[j].colindex + jdoc.colfix;
				tdata = jdoc.headers;
				if (jdoc.rowfix > 0 && tdata)
				{
					for (k=0; k < jdoc.rowfix; k++)
					{
						title += " " + (tdata[k].t[col] || tdata[k].c[col]);
					}
				}
				$("<span>Column " + col + "</span>&nbsp;&nbsp;: &nbsp;<span class='idv-br-stable-blue'>" + title + "</span><br>").appendTo(dv);
				let tb_outer = $("<table style='width:100%'><colgroup><col span='1' style='width: 50%;'></col><col span='1' style='width: 50%;'></col></colgroup></table>").appendTo(dv);
				let tb_outer_body = $("<tbody></tbody>").appendTo(tb_outer);
				let tb_outer_tr = $("<tr></tr>").appendTo(tb_outer_body);
				let tb_outer_td = $("<td></td>").appendTo(tb_outer_tr);
				let tb = $("<table></table>").appendTo(tb_outer_td);
				$.each([
					{rname: "S_AVG", key: "average"},
					{rname: "S_STDERR", key: "stderr"},
					{rname: "S_MEDIAN", key: "median"},
					{rname: "S_STDDEV", key: "stddev"},
					{rname: "S_VAR", key: "variance"},
					{rname: "S_KURT", key: "kurtosis"},
					{rname: "S_SKEW", key: "skewness"},
					{rname: "S_RAN", key: "ranges"},
					{rname: "S_MIN", key: "min"},
					{rname: "S_MAX", key: "max"},
					{rname: "S_SUM", key: "sum"},
					{rname: "S_COUNT", key: "count"}], function(key, value) {
						var nval = stat[j][value["key"]];
						if (nval === "" || nval === null || typeof(nval) == "undefined")
						{
							nval = "N/A";
						}
						tr = $("<tr></tr>").appendTo(tb);
						th = $("<td>" + IRm$.r1(value["rname"]) + "</td>").appendTo(tr);
						th = $("<td>" + nval + "</td>").appendTo(tr);
				});

				let freq_td = $("<td></td>").appendTo(tb_outer_tr);
				if (stat[j].frequencies && stat[j].frequencies.length)
				{
					let frequencies = stat[j].frequencies;

					let opt = {
						xAxis: {
							type: "category",
							axisTick: {
								show: false
							},
							axisLabel: {
								show: false
							}
						},
						yAxis: {type: "value"},
						series: [
							{
								data: frequencies,
								type: "bar"
							}
						]
					};

					let cdiv = $("<div style='width: 100%;height:250px;'></div>").appendTo(freq_td);
					var freq_vis = echarts.init(cdiv[0]);
					freq_vis.setOption(opt);
				}
			}
		}
	},
	
	initComponent : function() {
		this.title = IRm$.r1('T_STATISTICS');
		var panel = this;

		$s.apply(this, {
			padding: ig$.padding,
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					padding: ig$.padding,
					items: [
						{
							xtype: "panel",
							name: "mainpanel",
							border: 1,
							flex: 1,
							autoScroll:false,
							html: "",
							listeners: {
								resize: function(panel) {
									var h = $(panel.el.dom);
									h.css({"overflow-y": "scroll"});
								}
							}
						}
					]
				}
			],
			buttons: [
				{
					text: IRm$.r1('B_CLOSE'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					// this._init();
					this._reqstat();
				}
			}
		});
		
		IG$.statistics.superclass.initComponent.apply(this, arguments);
	}
});