	procMenu: function(view, el) {
		var me = this,
			sop = view.sheetoption,
			sopmodel = sop.model,
			cell = el.menu.cell, i,
			tgt, t, reload = false,
			sheetformula, sortmethod, sortcount, sortuid, 
			sortoption = (sopmodel) ? sopmodel.sortoption : null,
			mdf,
			T0, i, p;
		
		if (sopmodel)
		{
			mdf = sopmodel.mdf = sopmodel.mdf || {};
			sortoption = sopmodel.sortoption = sopmodel.sortoption || {};
		}
		
		if (cell)
		{
			T0 = cell.position;
			if (T0 == 1)
			{
				tgt = "rows";
			}
			else if (T0 == 2)
			{
				tgt = "cols";
			}
			else if (T0 == 3)
			{
				tgt = "measures";
			}
			
			t = (tgt && sopmodel[tgt].length > cell.index) ? sopmodel[tgt][cell.index] : null;
		}
		
		switch (el.cmd)
		{
		case "CMD_REMOVE":
			if (cell.position == 4)
			{
				sheetformula = sopmodel.sheet_formula;
				if (sheetformula)
				{
					for (i=0; i < sheetformula.length; i++)
					{
						if (sheetformula[i].node.fid == "formula_" + cell.index)
						{
							p = sheetformula.splice(i, 1);
							reload = true;
							break;
						}
					}
				}
			}
			else if (tgt && sopmodel.rows.length + sopmodel.cols.length + sopmodel.measures.length > 1)
			{
				p = sopmodel[tgt].splice(cell.index, 1);
				reload = true;
			}
			break;
		case "CMD_SORT":
			me.toolbarHandler("cmd_sort_option",t);
			break;
		case "CMD_FILTER":
			me.toolbarHandler("cmd_filter", t);
			break;
		case "CMD_STYLE":
			me.toolbarHandler("cmd_style", t);
			break;
		case "CMD_ASC":
			if (t.sortorder != "asc")
			{
				p = t.sortorder;
				t.sortorder = "asc";
				reload = true;
			}
			break;
		case "CMD_DESC":
			if (t.sortorder != "desc")
			{
				p = t.sortorder;
				t.sortorder = "desc";
				reload = true;
			}
			break;
		case "CMD_TOP5":
			sortmethod = "top";
			sortcount = 5;
			sortuid = t.uid;
			break;
		case "CMD_TOP10":
			sortmethod = "top";
			sortcount = 10;
			sortuid = t.uid;
			break;
		case "CMD_BTM5":
			sortmethod = "bottom";
			sortcount = 5;
			sortuid = t.uid;
			break;
		case "CMD_BTM10":
			sortmethod = "bottom";
			sortcount = 10;
			sortuid = t.uid;
			break;
		case "CMD_SHOWALL":
			sortmethod = "normal";
			sortcount = 0;
			sortuid = null;
			break;
		case "CMD_UNDO":
			reload = view.undolist();
			break;
		case "CMD_CLIPBOARD":
			var clip = view.getClipboardContent();
			IG$.clipboardCopy(clip);
			break;
		case "CMD_RUN_FILTER":
			if (mdf)
			{
				reload = true;
				if (el.menu.mdf)
				{
					mdf[cell.c] = el.menu.mdf;
				}
				else
				{
					delete mdf[cell.c];
				}
			}
			break;
		case "T_SUM":
		case "T_AVG":
		case "T_MIN":
		case "T_MAX":
		case "T_RANK":
		case "T_POT":
		case "T_CUMUL":
		case "T_INCR":
		case "T_DIFF":
		case "CL_FM":
		case "R_FMT":
			if (mdf)
			{
				me.formulaHandler(view, t, el.cmd);
			}
			break;
		default:
			if (el.cmd.substring(0, 7) == "detail:")
			{
				var duid = el.cmd.substring(7),
					dview,
					dobj,
					titem,
					tparams,
					detailview = sopmodel.detailview;
					
				for (i=0; i < detailview.length; i++)
				{
					if (detailview[i].uid == duid)
					{
						dview = detailview[i];
						break;
					}
				}
				
				if (dview)
				{
					dobj = {
						titem: {
							enabled: false,
							items: [],
							item_map: {}
						},
						tparams: {
							enabled: false,
							items: [],
							item_map: {}
						}
					};
					
					titem = dobj.titem;
					tparams = dobj.tparams;
					
					if (dview.titem)
					{
						titem.items = dview.titem.split(";");
						for (i=0; i < titem.items.length; i++)
						{
							if (titem.items[i])
							{
								titem.item_map[titem.items[i]] = 1;
							}
						}
						
						if (titem.items.length)
						{
							titem.enabled = true;
						}
					}
					
					if (dview.tparams)
					{
						tparams.items = dview.tparams.split(";");
						for (i=0; i < tparams.items.length; i++)
						{
							if (tparams.items[i])
							{
								tparams.item_map[tparams.items[i]] = 1;
							}
						}
						
						if (tparams.items.length)
						{
							tparams.enabled = true;
						}
					}
					
					var drillfilter = view.getDrillXML(dobj);
					if (drillfilter && drillfilter.children.length > 0)
					{
						me.showDetailView(view, dview, drillfilter);
					}
				}
			}
			break;
		}
		
		if (sortoption && ((sortmethod && sortmethod != sortoption.sortmethod) || (sortcount && sortcount != sortoption.sortcount) || (sortuid && sortuid != sortoption.sortmeasure)))
		{
			reload = true;
			sortoption.sortmethod = sortmethod;
			sortoption.sortcount = sortcount;
			sortoption.sortmeasure = sortuid;
		}
		
		if (reload == true)
		{
			me.contentchanged = true;
			// view.procUpdateReport();
			me.updatePivotCnt(me.activeSheet);
		}
	},

