	_exec_rpt: function(report, sheets) {
		var me = this,
			reportoption = report ? report.reportoption : me.reportoption,
			payloads = [],
			requests = [],
			views = [],
			newid = 0,
			request,
			pivotxml,
			payload;

		if (sheets.length)
		{
			pivotxml = reportoption.getCurrentPivot();
			
			$.each(sheets, function(i, sheet) {
				var view = sheet.view,
					req = sheet.req;
					
				if (req && req.payload)
				{
					if (pivotxml.bulkload) 
					{
						view.set_exec && view.set_exec("B_RPT_RUN");
						view.customLoad(true, true);
					}
					
					views.push(view);
					requests.push(req);
					payloads.push(req.payload);
					
					if (!req.payload.jobid)
					{
						newid++;
					}
				}
			});
			
			function load_report(payloads, pivotxml) {
				if (pivotxml.bulkload && payloads.length)
				{
					var req = new IG$._rpc$();
					req._ld = 1;
					req.init(me, 
						{
							ack: "olapservice",
							payload: payloads,
							mbody: pivotxml,
							meta_type: me.meta_type || "report"
						}, me, function(jdoc) {
							me._ldr = null;
							
							me.instance.navigateCompleted(me, "report_after_run", {request: req, results: jdoc});

							$.each(jdoc, function(k, ret) {
								var opt = requests[k],
									p = payloads[k],
									s = views[k], // report.sheets[parseInt(p.active)],
									olapset = s.olapset,
									callback = olapset.callback,
									sreq = new IG$._rpc$();
								
								sreq.init(me, {}, me, function(sdoc) {
									s.setLoading(false);
									olapset[opt.method](sdoc, opt.params);
									if (jdoc.length-1 == k)
										me.instance.navigateCompleted(me, "done");
								}, function(sdoc) {
									s.setLoading(false);
									callback && callback.execute({
										xdoc: sdoc,
										iserror: true
									});
									if (jdoc.length-1 == k)
										me.instance.navigateCompleted(me, "done");
								});
								
								sreq._sproc(me.instance, ret);
							});
						}, function(xdoc) {
							me._ldr = null;
							$.each(views, function(i, v) {
								v && v.set_exec && v.set_exec("B_RPT_ERR");
								v.setLoading(false);
							});

							me.instance.navigateCompleted(me, "done");
						});
					me._ldr = req;
					me.instance.navigateCompleted(me, "report_before_run", {request: req});
					req.send();
				}
				else
				{
					$.each(requests, function(i, request) {
						var req = new IG$._rpc$(),
							view = views[i];
						req._ld = 1;
						view && view.set_exec && view.set_exec("B_RPT_RUN");
						view && view.customLoad(true, true);
						req.init(me, 
							{
								ack: "olapservice",
								payload: request.payload,
								mbody: pivotxml,
								meta_type: me.meta_type || "report"
							}, me, function(jdoc) {
								me.instance.navigateCompleted(me, "report_after_run", {request: req, results: jdoc});
								view._ldr = null;
								var opt = request,
									p = request.payload,
									s = view, // report.sheets[parseInt(p.active)],
									olapset = s.olapset,
									callback = olapset.callback,
									sreq = new IG$._rpc$();
								
								view.setLoading(false);
								
								sreq.init(me, {}, me, function(sdoc) {
									olapset[opt.method](sdoc, opt.params);
								}, function(sdoc) {
									callback && callback.execute({
										xdoc: sdoc,
										iserror: true
									});
								});
								
								sreq._sproc(me.instance, {
									result: jdoc
								});

								me.instance.navigateCompleted(me, "done");
							}, function(xdoc) {
								view._ldr = null;
								view && view.set_exec && view.set_exec("B_RPT_ERR");
								view.setLoading(false);

								me.instance.navigateCompleted(me, "done");
							});
						view._ldr = req;
						me.instance.navigateCompleted(me, "report_before_run", {request: req});
						req.send();
					});
				}
			};
			
			if (newid)
			{
				var treq = new IG$._rpc$();
				
				treq.init(me, 
					{
						ack: "helpcontent",
						payload: {option: "newid", cnt: "" + newid},
						mbody: {},
					}, me, function(jdoc) {
						var n = 0;
						if (jdoc.nuid && jdoc.nuid.length)
						{
							$.each(payloads, function(i, payload) {
								if (!payload.jobid)
								{
									payload.jobid = jdoc.nuid[n++];
									views[i].jobid = payload.jobid;
								}
							});
						}
						load_report(payloads, pivotxml);
					}
				);
				treq.send();
			}
			else
			{
				load_report(payloads, pivotxml);
			}
		}
	},
	
