	updateLayout: function(firstrender) {
		var me = this,
			i,
			// sheetview,
			sheet,
			sop,
			sheets = me.sheets,
			dzone = me.dzone,
			ubody;
			// _root = dzone._root,
			// ubody, _nc;

		if (!firstrender)
		{
			for (i=0; i < me.reportoption.sheets.length; i++)
			{
				sop = me.reportoption.sheets[i];

				if (sheets.length > i)
				{
					sheet = sheets[i];
					ubody = dzone.getBox(sop.model.layoutinfo.docid);
				}
				else
				{
					ubody = me.appendBox(null, sop.model);
					
					sop.model.layoutinfo.docid = ubody.docid;
					sheet = me.createSheet(i, sop, ubody);
					sheet.reportoption = me.reportoption;

					ubody.view = sheet;
					ubody.objtype = "SHEET";
					ubody.validateProperty();

					ubody.setReportOption(sop);

					me.sheets.push(sheet);
					me.sheets_id[sheet.sheet_id] = sheet;
				}

				if (ubody)
				{
					ubody.setTitle(sop.name || "");
					ubody.showTitle(!sop.hidetitle);
				}
				sheets[i].sheetoption = sop;
				sheets[i].applyOptions();
			}
		}
		else
		{
			for (i=0; i < me.sheets.length; i++)
			{
				// mlayout.items.push(me.sheets[i]);
				sop = me.reportoption.sheets[i];
				sheets[i].sheetoption = sop;
				sheets[i].applyOptions();
			}
		}
	},

