	updateFormula: function(view) {
		var me = this,
			sheetview = view,
			sheetindex = sheetview.sheetindex,
			tbresult = me.down("[name=tbresult]"),
			sel = sheetview.getSelection(),
			mtext = "", i, sum = 0,
			rec;

		if (sel && sel.length > 0)
		{
			for (i=0; i < sel.length; i++)
			{
				rec = sel[i];
				if (rec.code && (rec.position == 3 || rec.position == 4))
				{
					sum = sum + parseFloat(rec.code);
				}
			}

			if (IG$.isNumber(sum))
			{
				mtext = "SUM: " + IG$.NumberFormat("0,000.00", sum);
			}
		}
		tbresult && tbresult.setText(mtext);
	},

