	clipboardCopy: function() {
		var me = this,
			activeview = me.sheets[me.activeSheet],
			hasnoresult = activeview ? activeview.updateNoData() : true,
			mresult;
			
		if (activeview && activeview.mresults && activeview.mresults.results)
		{
			mresult = activeview.mresults.results[0];
		}

		if (mresult && !hasnoresult)
		{
			var dlge = new IG$.c$ClpBrd({
				instance: me.instance,
				sheetview: activeview,
				mresult: mresult
			});
			dlge.show();
		}
		else
		{
			IG$.ShowError(IRm$.r1("M_NO_DATA"), me);
		}
	},

	showReportOption: function(pcube_objects, callback, sheetoption, fcreate, fappend) {
		var me = this,
			// req = new IG$._rpc$(),
			itemtype,
			jdoc;
			
		// me.removeListener("show", me.showReportOption, me);
		
		itemtype = me.itemtype || "Report";
		
		if (!me.reportoption)
		{
			fcreate = 1;
			
			jdoc = me.makeTempReportMeta({type: itemtype});
			
			me.reportoption = new IG$.clReports(jdoc, me.meta_type);
			
			me.opt_editmode = true;
		}
		
		var dlg = new IG$._IB6/*reportOption*/({
			instance: me.instance,
			modal: true,
			cubeuid: me.cubeuid,
			fcreate: fcreate,
			fappend: fappend,
			reportoption: me.reportoption,
			sheetoption: sheetoption,
			callback: new IG$.callBackObj(me, function(dlg, cancel, template) {
				var me = this;
				
				var doproc = function() {
					if (fcreate)
					{
						if (cancel === true)
						{
							me.close();
							return;
						}

						if (me.reportoption && !jdoc)
						{
							jdoc = me.makeTempReportMeta({type: itemtype});
						}
						
						jdoc.content.cube_objects = dlg.cubeobj ? [dlg.cubeobj] : null;
						
						me.rs_loadContent(jdoc, true, cancel === true);
						me.continueReportOption(dlg);
						me.load_cube = null;
						me.cubeuid = null;
					}
					else if (cancel !== true)
					{
						me.continueReportOption(dlg);
						callback && callback.execute(dlg.cubeobj);
					}
					else if (cancel === true)
					{
						IG$.ShowWarning(IRm$.r1("E_CANCEL_BOBJ_SEL"), me);
					}
				};
				
				if (template && template.get("nodepath"))
				{
					var req = new IG$._rpc$(),
						rpt = me.reportoption;
					
					req.init(me, 
						{
							ack: "helpcontent",
							payload: {act: "get", nodepath: template.get("nodepath"), name: template.get("name")},
							mbody: {option: "rpt_tmpl"}
						}, me, function(tdoc) {
							tdoc.cube_objects = dlg.cubeobj ? [dlg.cubeobj] : null;
							var odoc = {
								type: rpt.type,
								uid: rpt.uid,
								nodepath: rpt.nodepath,
								name: rpt.name,
								content: tdoc
							};
							
							me._template_load = true;
							me.rs_loadContent(odoc, true, cancel === true);
							me.continueReportOption(dlg);
							me.load_cube = null;
							me.cubeuid = null;
							
						}, function() {
							doproc();
						});
					req.send();
				}
				else
				{
					doproc();
				}
			})
		});
		IG$.checkLogin(me, dlg);
	},
	
