			m$dw = window.m$dw || 0;

		me.updateExpOpt();

		dzone.clearAll();

		me.sheets = [];
		me.sheets_id = {};

		layoutinfo = reportoption.layoutinfo;
		me.ctrls = reportoption.ctrls;

