	prepGridStyles: function(dataquerymode) {
		var me = this,
			i,
			sheetoption = me.sheetoption,
			sm = sheetoption.model,
			itemstyle, 
			sheetformula = sm.sheet_formula || [],
			rows = sm.rows,
			cols = sm.cols,
			measures = sm.measures,
			rptitem,
			stylemap = {},
			baseitems = [],
			baseitems_map = {},
			st,
			suid
			name_map = {};
		
		itemstyle = sm.styles = sm.styles || [];
		
		let styles = {};
		
		for (i=0; i < itemstyle.length; i++)
		{
			st = itemstyle[i];
			suid = st.uid + "_" + (st.rptseq || "0") + (st.fid ? "_" + st.fid : ""); 
			stylemap[suid] = st;
		}
		
		if (dataquerymode == "M_REPORT")
		{
			baseitems.push({
				items: rows,
				m: 0,
				rptseq: 0
			});
			
			for (i=0; i < sm.report_items.length; i++)
			{
				rptitem = sm.report_items[i];
				
				baseitems.push(
					{
						items: rptitem.cols,
						m: 0,
						rptseq: i
					} 
				);
				baseitems.push({
						items: rptitem.measures,
						m: 1,
						rptseq: i
					}
				);
			}
		}
		else
		{
			baseitems = [
				{
					items: rows,
					m: 0,
					rptseq: 0
				}, 
				{
					items: cols,
					m: 0,
					rptseq: 0
				}, 
				{
					items: measures,
					m: 1,
					rptseq: 0
				},
				{
					items: sheetformula || [],
					m: 2,
					rptseq: 0
				}
			];
		}
		
		$.each(baseitems, function(i, bitem) {
			$.each(bitem.items, function(j, mitem) {
				if (bitem.m == 2)
				{
					return;
				}
				else
				{
					name_map[mitem.uid] = mitem.name;
				}
			});
		});
		
		$.each(baseitems, function(i, bitem) {
			$.each(bitem.items, function(j, mitem) {
				var key,
					st;
				
				if (bitem.m == 2)
				{
					key = mitem.baseuid + "_" + bitem.rptseq + "_" + mitem.fid;
					if (name_map[mitem.baseuid])
					{
						mitem.basename = name_map[mitem.baseuid];
					}
				}
				else
				{
					key = mitem.uid + "_" + bitem.rptseq;
				}
				
				baseitems_map[key] = mitem;
				
				st = stylemap[key];
				
				if (st)
				{
					if (bitem.m == 2)
					{
						st.name = mitem.basename + " (" + (mitem.title || "") + ")";
					}
					else
					{
						st.name = mitem.name;
					}
					st.rptseq = bitem.rptseq;
				}
			});
		});
		
		for (i=itemstyle.length-1; i>=0; i--)
		{
			st = itemstyle[i];
			suid = st.uid + "_" + (st.rptseq || "0") + (st.fid ? "_" + st.fid : ""); 
			
			if (!baseitems_map[suid])
				itemstyle.splice(i, 1);
		}
	},
	
