	getTime: function(p) {
		var me = this,
			r = "",
			t;
		
		$.each(["h", "m", "s"], function(i, k) {
			var ctrl = me.down("[name=c2_r" + k + p + "]"),
				mv = ctrl.getValue();
			r += (i > 0 ? ":" : "") + (mv < 10 ? "0" : "") + mv;
		});
		
		return r;
	},
	
