	rs_getSID: function(jdoc) {
		var me = this,
			pval = jdoc && jdoc.length ? jdoc[0] : null,
			scoption,
			sctime,
			stemp,
			fcomp, fcomp_ch,
			_is_report = me._is_report,
			_is_mongomr = me._is_mongomr;

		if (pval)
		{
			if (_is_report)
			{
				me.req = pval.requests || [];
				me.req_trigger = pval.trigger;
				me.uid = pval.objuid;
				me._set_syncopt();
			}
			else if (_is_mongomr)
			{
				me.req = pval.requests || [];
				me.uid = pval.objuid;
				me._set_syncopt();
			}
			else if (pval.programs && pval.programs.length)
			{
				me.down("[name=scp]").setValue(pval.programs[0].java_class);
				
				setTimeout(function() {
					var plist = pval.programs[0].params; 
					if (plist)
					{
						var _params = me.down("[name=_params]"),
							pp = {};
							
						$.each(plist, function(i, p) {
							pp[p.name] = p.value;
						});
						
						_params.setAllValues(pp, true);
					}
				}, 10);
			}
			else
			{
				me._set_syncopt();
			}
			me.down("[name=scname]").setValue(pval.name);
			me.down("[name=sctype]").setValue(pval.sctype);
			me.down("[name=pstatus]").setValue(pval.pstatus == "N" ? "N" : "A");
			me.down("[name=a_1]").setValue(pval.a_1);
			me.down("[name=a_1a]").setValue(pval.a_1a);
			me.down("[name=a_1b]").setValue(pval.mailcc);
			me.down("[name=a_1c]").setValue(pval.message);
			scoption = pval.scoption || "";
			
			if (pval.sctype == "C1")
			{
				scoption = scoption.split(":");
				scoption[0] && me.down("[name=c1_hh]").setValue(Number(scoption[0]));
				scoption[1] && me.down("[name=c1_mm]").setValue(Number(scoption[1]));
				scoption[2] && me.down("[name=c1_ss]").setValue(Number(scoption[2]));
			}
			else if (pval.sctype == "C2")
			{
				scoption = scoption.split("|");
				var pdate = function(value) {
					var n = IG$.getDateParse(value),
						dt;
					
					if (n.y && n.M && n.d)
					{
						dt = new Date(Number(n.y), Number(n.M)-1, Number(n.d));
					}
					return dt;
				}
				
				sctime = scoption[2] || "";
				sctime = sctime.split(":");
				scoption[0] && me.down("[name=c2_from]").setValue(pdate(scoption[0]));
				scoption[1] && me.down("[name=c2_to]").setValue(pdate(scoption[1]));
				sctime[0] && me.down("[name=c2_hh]").setValue(sctime[0]);
				sctime[1] && me.down("[name=c2_mm]").setValue(sctime[1]);
				sctime[2] && me.down("[name=c2_ss]").setValue(sctime[2]);
				
				// scoption[5] && me.down("[name=c2_ss]").setValue(scoption[4]);
				
				if (scoption[3])
				{
					stemp = ";" + scoption[3] + ";";
					
					fcomp = me.down("[name=f_dw]");
					fcomp_ch = fcomp.checkboxCmp;
					
					fcomp_ch.setValue(true);
					
					$.each(["SU", "MO", "TU", "WE", "TH", "FR", "SA"], function(k, m) {
						var p = fcomp.down("[name=c_" + m + "]");
						if (stemp.indexOf(";" + m + ";") > -1)
						{
							p.setValue(true);
						}
					});
				}
				
				if (scoption[4])
				{
					stemp = ";" + scoption[4] + ";";
					
					fcomp = me.down("[name=fs_dm]");
					fcomp_ch = fcomp.checkboxCmp;
					
					fcomp_ch.setValue(true);
					
					for (i=0; i < 31; i++)
					{
						var p = fcomp.down("[name=f_" + (i) + "]");
						if (stemp.indexOf(";" + i + ";") > -1)
						{
							p.setValue(true);
						}
					}
					
					if (stemp.indexOf(";lday;") > -1)
					{
						fcomp.down("[name=f_lday]").setValue(true);
					}
				}
				
				if (scoption[5])
				{
					stemp = ";" + scoption[4] + ";";
					
					fcomp = me.down("[name=fs_m]");
					fcomp_ch = fcomp.checkboxCmp;
					
					fcomp_ch.setValue(true);
					
					for (i=0; i < 12; i++)
					{
						var p = fcomp.down("[name=m_" + (i) + "]");
						if (stemp.indexOf(";" + i + ";") > -1)
						{
							p.setValue(true);
						}
					}
				}
				
				scoption[6] && me.down("[name=c2_r1]").setValue(scoption[6] == "T" ? "R" : "");
				scoption[7] && me.down("[name=c2_ri]").setValue(scoption[7]);
				scoption[8] && me.down("[name=c2_rp]").setValue(scoption[8]);
				
				if (scoption[9])
				{
					stemp = scoption[9].split(":");
					if (stemp.length == 3)
					{
						me.down("[name=c2_rh1]").setValue(parseInt(stemp[0]));
						me.down("[name=c2_rm1]").setValue(parseInt(stemp[1]));
						me.down("[name=c2_rs1]").setValue(parseInt(stemp[2]));
					}
				}
				
				if (scoption[10])
				{
					stemp = scoption[10].split(":");
					if (stemp.length == 3)
					{
						me.down("[name=c2_rh2]").setValue(parseInt(stemp[0]));
						me.down("[name=c2_rm2]").setValue(parseInt(stemp[1]));
						me.down("[name=c2_rs2]").setValue(parseInt(stemp[2]));
					}
				}
			}
			else if (pval.sctype == "C3")
			{
				scoption = scoption.split(":");
				scoption[0] && me.down("[name=c3_hh]").setValue(Number(scoption[0]));
				scoption[1] && me.down("[name=c3_mm]").setValue(Number(scoption[1]));
			}

			me.getRptTrg();
		}
	},
	
	_update_parmas: function(nvalue) {
		var me = this,
			programs = me.programs,
			i,
			program,
			_params = me.down("[name=_params]");
			
		// clear params section
		
		_params.removeAll();
			
		for (i=0; i < programs.length; i++)
		{
			if (programs[i].java_class == nvalue)
			{
				program = programs[i];
				break;
			}
		}
		
		_params.setVisible(false);
		
		ig$._sc_scr = ig$._sc_scr || {};
		
		if (program.ui_screen && program.ui_screen.length)
		{
			var p = program.ui_screen.join("\n");
			
			try
			{
				var dyn = new IG$.cDynScript('cls_prog_scr' + program.name, 0),
					script = IG$._decodeVal(p);
					
				dyn.loadScript(script);
			}
			catch (e)
			{
				void 0;
				IG$.ShowError("Error on dynamic screen loader", null, null, {errstack: e.stack});
			}
		}
		
		if (program.ui_script && program.ui_script.length)
		{
			var p = program.ui_script.join("\n");
			
			try
			{
				var dyn = new IG$.cDynScript('cls_prog' + program.name, 0),
					script = "ig$._sc_scr['" + program.name + "'] = " + IG$._decodeVal(p);
					
				dyn.loadScript(script);
			}
			catch (e)
			{
				void 0;
				IG$.ShowError("Error on dynamic script loader", null, null, {errstack: e.stack});
			}
		}
		
		var prog_scripts = ig$._sc_scr[program.name] || {};
		
		if (program && program.ui_layout && program.ui_layout.length)
		{
			try
			{
			var _update_layout = function(p) {
					if (p.listeners)
					{
						$.each(p.listeners, function(k, listener) {
							var lname = listener;
							
							p.listeners[k] = function() {
								var arg = arguments;
								
								if (prog_scripts[lname])
								{
									return prog_scripts[lname].apply(me, arg);
								}
								else
								{
									IG$.ShowError("script " + lname + " not defined!");
								}
							}
						});
					}
					else if (p.handler)
					{
						var hname = p.handler,
							h = prog_scripts[p.handler];
						
						p.handler = function() {
							if (h)
							{
								return h.apply(me);
							}
							else
							{
								IG$.ShowError("handler " + hname + " not defined!");
							}
						}
					}
					
					if (p.items && p.items.length)
					{
						$.each(p.items, function(k, items) {
							_update_layout(items);
						});
					}
				};
				
				var p = JSON.parse(IG$._decodeVal(program.ui_layout.join("\n")));
				
				_update_layout(p);
			
				if (p && typeof(p) == "object")
				{
					_params.setVisible(true);
					program.__dw = _params.add(p);
				}
				}
			catch (e)
			{
				void 0;
				IG$.ShowError("Error on layout info : ", null, null, {errstack: e.stack});
			}
			}
	},
	
