IG$.drilltarget = function(drilltarget, edrill) {
	var me = this,
		i, j,
		tval,
		t1,
		tname,
		titem,
		tparams,
		isdrill,
		isparameter;
	
	me.tsheets = tsheets = {};	
	me._edrill = edrill;
	
	if (drilltarget)
	{
		for (i=0; i < drilltarget.length; i++)
		{
			tval = drilltarget[i];
			
			if (tval)
			{
				isparameter = tval.isparameter;
				
				titem = {
					enabled: false,
					items: [],
					item_map: {}
				};
				
				tparams = {
					enabled: false,
					items: [],
					item_map: {}
				};
				
				tname = tval.sid;
				isdrill = edrill ? true : tval.usedrill;
				t1 = tval.item;
				if (t1)
				{
					if (t1 == "none")
					{
						titem.enabled = true;
					}
					else
					{
						titem.items = t1.split(";");
						
						for (j=0; j < titem.items.length; j++)
						{
							if (titem.items[j])
							{
								titem.enabled = true;
								titem.item_map[titem.items[j]] = 1;
							}
						}
					}
				}
				t1 = tval.params || null;
				if (t1)
				{
					if (t1 == "none")
					{
						tparams.enabled = true;
					}
					else
					{
						tparams.items = t1.split(";");
						
						for (j=0; j < tparams.items.length; j++)
						{
							if (tparams.items[j])
							{
								tparams.enabled = true;
								tparams.item_map[tparams.items[j]] = 1;
							}
						}
					}
				}
				
				me.tsheets[tname] = {
					name: tname,
					isdrill: isdrill,
					tparams: tparams,
					titem: titem,
					isparameter: isparameter
				};
			}
		}
	}
}

IG$.drilltarget.prototype = {
	isDrillTarget: function(sheetid, shid) {
		var me = this,
			sobj = me.tsheets[sheetid],
			r;
		
		// for supporting existing settings
		if (!sobj && shid)
		{
			sobj = me.tsheets[shid];
		}
		
		if (me._edrill || (sobj && sobj.isdrill))
		{
			if (sobj && sobj.isdrill)
			{
				r = sobj;
			}
			else
			{
				r = {
					name: sheetid,
					isdrill: true,
					isparameter: sobj ? sobj.isparameter : false,
					titem: {
						enabled: false,
						items: [],
						item_map: {}
					},
					tparams: {
						enabled: false,
						items: [],
						item_map: {}
					}
				};
			}
		}
		else
		{
			r = {isdrill: false};
		}
		
		return r;
	}
};

