IG$._IE5/*getStyleName*/ = function(mresult, r, c) {
	if (mresult.styledata.length > r && mresult.styledata[r].length > c && mresult.styledata[r][c] != "")
	{
		return " class='" + mresult.styledata[r][c] + "'";
	}
	
	return "";
}

IG$.clFilter = function(node) {
	var me = this;
	
	me.model = node || {};
	
	$s.defaults(me.model, {
		fields: [],
		right_fields: [],
		delimiter: ";",
		values: []
	});
}

IG$.clFilter.prototype = {
	getDesc: function() {
		var me = this,
			r = "",
			i,
			model = me.model,
			fields = model.fields;
		
		if (model.left_expression)
		{
			r = model.left_expression;
		}
		else
		{
			for (i=0; i < fields.length; i++)
			{
				r = (i == 0) ? fields[i].name : r + ", " + fields[i].name;
			}
		}
		
		r += "\n" + me._d1/*getOperatorDesc*/(model.operator, model.opisnot, 1) + "\n(";
		
		if (model.valuetype == "field")
		{
			if (model.expression)
			{
				r += model.expression;
			}
			else
			{
				r += (model.right_fields && model.right_fields.length ? model.right_fields[0].name : "");
				if (model.operator == 8)
				{
					r += " AND " + (model.right_fields && model.right_fields.length > 1 ? model.right_fields[1].name : "");
				}
			}
		}
		else
		{
			r += me.getValueDesc(model.values);
		}
		
		r += ")";
		
		return r.substring(0, 50);
	},
	getValueDesc: function(values) {
		var me = this,
			r = "",
			i, sval;
		
		if (values && values.length > 0)
		{
			for (i=0; i < values.length; i++)
			{
				r += (i > 0) ? (me.delimiter || ",") : "";
				sval = (values[i].value || values[i].code || "");
				sval = IG$._decodeVal(sval);
				r += sval;
			}
		}
		
		return r;
	},
	
	_d1/*getOperatorDesc*/: function(op, opisnot, isdesc) {
		var opcodes = IG$.filteropcodes,
			opvalue = opcodes[op].locale,
			oploc = opcodes[op].lcode;
		
		return opvalue;
	},
	
	loadData: function(panel, callback) {
		var me = this,
			uid = me.fields[0].uid,
			req = new IG$._rpc$();
		
		me.dataLoaded = true;
		me.data = [];
		
		req.init(panel, 
			{
				ack: "olapservice",
				payload: {uid: uid, option: "valuelist"},
				mbody: {}
			}, me, me.rs_loadData, null, callback);
		req.send();
	},
	rs_loadData: function(jdoc, callback) {
		var me = this,
			uid = me.fields[0].uid,
			result = jdoc; // new IG$._ICd/*clValueList*/(jdoc, uid);
		
		me.result = result;
		
		if (callback)
		{
			callback.execute();
		}
	}
};

IG$.clFilterGroup = function(node) {
	var me = this,
		p;
	
	if (node)
	{
		me.name = node.name;
		me.authuid = node.authuid;
		me.authname = node.authname;
		me.active = node.active;
		me.ftype = node.ftype;
	}
	
	me.subGroups = [];
	me.subConditions = [];
}

IG$.clFilterGroup.prototype = {
	findItem: function(uid) {
		var me = this,
			r = this.T1a/*findSubItem*/(uid, me);
		return r;
	},
	
	T1a/*findSubItem*/: function(uid, group) {
		var i, j,
			r,
			condition,
			_dff = group.subConditions,
			_dfs = group.subGroups,
			fields;
			
		for (i=0; i < _dff.length; i++)
		{
			condition = _dff[i];
			fields = condition.fields;
			if (fields && fields.length > 0)
			{
				for (j=0; j < fields.length; j++)
				{
					if (fields[j].uid == uid)
					{
						r = condition;
						break;
					}
				}
			}
			
			if (r)
			{
				break;
			}
		}
		
		if (!r)
		{
			for (i=0; i < _dfs.length; i++)
			{
				r = this.T1a/*findSubItem*/(uid, _dfs[i]);
				if (r)
				{
					break;
				}
			}
		}
		
		return r;
	},
	
	TX: function() {
		var me = this,
			x = {
				ftype: me.ftype || "condition"
			},
			i,
			cf,
			cg,
			isauthfilter = false,
			subConditions = me.subConditions,
			subGroups = me.subGroups;
			
		if (me.authuid && me.authname)
		{
			isauthfilter = true;
			x = {
				authuid: me.authuid,
				authname: me.authname,
				active: me.active,
				children: []
			};
		}
	
		if (subConditions.length > 0 || subGroups.length > 0)
		{
			x.ftype = "group";
			x.name = me.name;
			x.children = [];
			
			if (subConditions.length > 0)
			{
				for (i=0; i < subConditions.length; i++)
				{
					cf = subConditions[i];
					cf.ftype = "condition";
					x.children.push(cf.TX());
				}
			}
			
			if (subGroups.length > 0)
			{
				for (i=0; i < subGroups.length; i++)
				{
					cg = subGroups[i];
					cg.ftype = "group";
					x.children.push(cg.TX());
				}
			}
		}
		
		return x;
	}
}

