IG$.clStyleItem = function(node, itemtype) {
	var me = this;
	me.itemtype = itemtype;	
	me._mc = node || {};
	me._mc.template = IG$._encodeVal(me._mc.template); 
}

IG$.clStyleItem.prototype = {
	applyBaseStyle: function(base) {
		var me = this,
			i, k;
		
		for (k in base._mc)
		{
			if (typeof me._mc[k] == "undefined" || me._mc[k] === null || me._mc[k] === -1)
			{
				me._mc[k] = base._mc[k];
			}
		}
	},
	forceBsStyl: function(base, substract) {
		var me = this,
			cmc = me._mc,
			bmc = base._mc, 
			k;
		
		if (!bmc || !cmc)
			return;
		
		for (k in bmc)
		{
			if (substract)
			{
				if (cmc[k] == bmc[k] || cmc[k] == "")
				{
					delete cmc[k];
				}
			}
			else
			{
				cmc[k] = bmc[k];
			}
		}
	},
	getData: function(bmc) {
		var me = this,
			_mc = me._mc,
			_bmc = bmc ? bmc._mc : null,
			mc = {},
			k, n, v;
			
		for (k in _mc)
		{
			if (k != "name")
			{
				v = _mc[k];
				
				if (_bmc && _bmc[k] === v)
				{
					v = null;
				}
				else
				{
					mc[k] = v;
				}
			}
			else
			{
				mc[k] = _mc[k];
			}
		}
			
		return mc;
	}
}

