IG$.n$brwser = $s.extend($s.panel, {
	layout: "card",
	bodyPadding: 0,
	cmode: 0,
	
	navigateTree: function(dt) {
		var p = this,
			l = p.getLayout(),
			ltext,
			btn = p.down("[name=btnsearchitem]");
		
		p.cmode = 0;
		ltext = IRm$.r1("B_SEARCH");
		btn.setText(ltext);
		l.setActiveItem(p.cmode);
		
		p.api.navigateTree(dt);
	},
	
	initComponent: function() {
		var me = this;
		
		me.api = new IG$.naviTree({
			instance: me.instance,
			owner: me,
			mainPanel: me.mainPanel,
			showtoolbar: false,
			layout: "fit"
		});
		
		me.search = new IG$.n$brwSch({
			instance: me.instance,
			owner: me
		}); 
		
		$s.apply(me, {
			layout: "card",
			region: me.region || "west",
			split:true,
			header: false,
			collapsible: true,
			margins:"0 0 0 0",
			cmargins:"0 0 0 0",
			lines:false,
			autoScroll:false,
			animate: true,
			
			items: [
				me.api,
				me.search
			]
		});
		
		me.tbarobj = [" ",
			{
				xtype: "button",
				name: "btnsearchitem",
				text: IRm$.r1("B_SEARCH"),
				handler: function() {
					var p = this,
						l = p.getLayout(), ltext,
						btn = p.down("[name=btnsearchitem]");
					
					p.cmode = (p.cmode == 1) ? 0 : 1;
					ltext = (p.cmode == 0) ? IRm$.r1("B_SEARCH") : IRm$.r1("B_TREEVIEW");
					
					btn.setText(ltext);
					l.setActiveItem(p.cmode);
				},
				scope: me
			}, 
			{
				iconCls: "icon-refresh",
				tooltip: IRm$.r1("L_REFRESH"),
				handler: function() {
					var me = this,
						api = me.api;
					api.refTopNode();
				},
				scope: me
			}
		];
		
		
		if (me.showallcheckselect == true)
		{
			me.tbarobj.push({
				iconCls: "icon-toolbar-remove",
				tooltip: IRm$.r1("L_DELETE_CHECKED"),
				handler: function() {
					var me = this;
					me.api.removeSelItems();
				},
				scope: me
			});
			
			me.tbarobj.push({
				iconCls: "icon-toolbar-move",
				tooltip: "Move Selection",
				handler: function() {
					var me = this;
					me.api.moveSelItems();
				},
				scope: me
			});
		}
			
		me.tbarobj.push("->");
		
		me.toolbar = Ext.create("Ext.toolbar.Toolbar", {
			items: me.tbarobj
		});
		
		Ext.apply(me, {
			tbar: me.toolbar
		});
			  
		IG$.n$brwser.superclass.initComponent.call(me);
	}
});