IG$.$d_hlconfig = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: {
		type: 'vbox',
		align: 'stretch'
	},
	
	closable: false,
	resizable:false,
	width: 500,
	height: 440,
		
	seq: 0,
	
	_confirm: function() {
		var me = this;
		me.commit_f();
		me.callback && me.callback.execute();
		me.close();
	},
	
	init_f: function() {
		var me = this,
			req = new IG$._rpc$();
		
		req.init(me, 
			{
				ack: "appoption",
				payload: {address: "ReportStyle"},
				mbody: {}
			}, me, function(jdoc) {
				var me = this,
					highlight = me._piobj._mc.highlight || [],
					hlitem,
					hl = [],
					i, j,
					grdhl = me.down("[name=grdhl]"),
					tnode = jdoc.themes[0].custom_styles,
					cs = [];
					
				for (i=0; i < highlight.length; i++)
				{
					hlitem = highlight[i];
					hlitem.seq = me.get_sid();
					hlitem.itemname = hlitem.name;
					hlitem.value_desc = [];
					if (hlitem.values)
					{
						for (j=0; j < hlitem.values.length; j++)
						{
							hlitem.value_desc.push(hlitem.values[j].code);
						}
					}
					hlitem.value_desc = hlitem.value_desc.join(",");
					hl.push(hlitem);
				}
				
				grdhl.store.loadData(hl);
				
				if (tnode)
				{
					for (j=0; j < tnode.length; j++)
					{
						cs.push({
							name: tnode[j].name
						});
					}
				}
				
				me.__global_cs = cs;
			}, null);
		req.send();
	},
	

	commit_f: function() {
		var me = this,
			highlight = me._piobj._mc.highlight,
			grdhl = me.down("[name=grdhl]"),
			store = grdhl.store,
			i, j, rec, new_hloption = [];
			
		for (i=0; i < store.data.items.length; i++)
		{
			rec = store.data.items[i];
			
			for (j=0; j < highlight.length; j++)
			{
				if (highlight[j].seq == rec.get("seq"))
				{
					new_hloption.push(highlight[j]);
					break;
				}
			}
		}
			
		me._piobj._mc.highlight = new_hloption;
	},
	
	make_new_option: function(hlobj) {
		var me = this,
			hlobj = hlobj,
			dlg = new IG$.$w_hl_config_item({
				instance: me.instance,
				_piobj: me._piobj,
				__global_cs: me.__global_cs,
				hlobj: hlobj,
				callback: new IG$.callBackObj(me, me.rs_make_new_option)
			});
		
		IG$.checkLogin(me, dlg);
	},
	
	rs_make_new_option: function(item) {
		var me = this,
			grdhl = me.down("[name=grdhl]"),
			i, rec, p,
			highlight;
		
		highlight = me._piobj._mc.highlight = me._piobj._mc.highlight || [];
		
		if (item.isnew == true)
		{
			delete item["isnew"];
			highlight.push(item);
			grdhl.store.add(item);
		}
		else
		{
			for (i=0; i < grdhl.store.data.items.length; i++)
			{
				p = grdhl.store.data.items[i];
				if (p.get("seq") == item.seq)
				{
					rec = p;
					break;
				}
			}
			
			if (rec)
			{
				rec.set("name", item.name);
				rec.set("delimiter", item.delimiter);
				rec.set("itemname", item.itemname);
				rec.set("uid", item.uid);
				rec.set("operator", item.operator);
				rec.set("stylename", item.stylename);
				rec.set("styleuid", item.styleuid);
				rec.set("apprange", item.apprange);
				rec.set("appset", item.appset);
				rec.set("values", item.values);
				rec.set("value_desc", item.value_desc);
			}
		}
	},
	
	get_sid: function() {
		var me = this;
		
		me.seq++;
		
		return "seq_" + me.seq;
	},
	
	initComponent : function() {
		var me = this;

		me.title = IRm$.r1('T_HL_OPT');
				 
		$s.apply(this, {
			padding: ig$.padding,
			
			items: [
				{
					xtype: "form",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					autoScroll: true,
					
					defaults: {
						anchor: "100%"
					},
					items: [
						{
							xtype: "fieldcontainer",
							layout: {
								type: "hbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "displayfield",
									value: IRm$.r1("L_HL_DESC"),
									flex: 1
								},
								{
									xtype: "button",
									text: IRm$.r1("L_ADD_NEW"),
									handler: function() {
										var me = this,
											hlobj = {
												isnew: true,
												seq: me.get_sid()
											};
										
										me.make_new_option(hlobj);
									},
									scope: this
								}
							]
						},
						{
							xtype: "gridpanel",
							name: "grdhl",
							flex: 1,
							store: {
								xtype: "store",
								fields: [
									"name", "delimiter", "itemname", "uid", "operator", "stylename", "styleuid", "apprange", "appset", "seq", "values"
								]
							},
							selType: "checkboxmodel",
							selModel: {
								mode: "SINGLE"
							},
							tbar: [
								{
									iconCls: "icon-toolbar-moveup",
									text: IRm$.r1("L_MOVE_UP"),
									handler: function() {
										var grdhl = this.down("[name=grdhl]"),
											sm = grdhl.getSelectionModel(),
											sel = sm.getSelection(),
											rec, ri;
										
										if (sel && sel.length == 1)
										{
											rec = sel[0];
											ri = grdhl.store.indexOf(rec);
											if (ri > 0)
											{
												grdhl.store.remove(rec);
												rec = grdhl.store.insert(ri-1, rec);
												sm.select(rec, true);
											}
										}
									},
									scope: this
								},
								{
									xtype: "button",
									iconCls: "icon-toolbar-movedown",
									text: IRm$.r1("L_MOVE_DOWN"),
									handler: function() {
										var grdhl = this.down("[name=grdhl]"),
											sm = grdhl.getSelectionModel(),
											sel = sm.getSelection(),
											rec, ri;
										
										if (sel && sel.length == 1)
										{
											rec = sel[0];
											ri = grdhl.store.indexOf(rec);
											if (ri+1 < grdhl.store.data.items.length)
											{
												grdhl.store.remove(rec);
												rec = grdhl.store.insert(ri+1, rec);
												sm.select(rec, true);
											}
										}
									},
									scope: this
								}
							],
							columns: [
								{
									xtype: "gridcolumn",
									text: IRm$.r1("B_NAME"),
									dataIndex: "itemname",
									tdCls: "igc-td-link",
									flex: 1
								},
								{
									xtype: "gridcolumn",
									text: IRm$.r1("B_ST_NAME"),
									dataIndex: "stylename",
									flex: 1
								},
								{
									xtype: "gridcolumn",
									text: IRm$.r1("L_CONDITION"),
									dataIndex: "operator",
									width: 60
								},
								{
									xtype: "gridcolumn",
									text: IRm$.r1("B_VALUE"),
									dataIndex: "value_desc",
									flex: 1
								},
								{
									xtype: "actioncolumn",
									width: 40,
									items: [
										{
											iconCls: "icon-grid-delete",
											tooltip: IRm$.r1("B_DELETE"),
											handler: function (grid, rowIndex, colIndex) {
												var me = this,
													i,
													hl
													rec = grid.store.getAt(rowIndex),
													h = me._piobj._mc.highlight;
												
												for (i=0; i < h.length; i++)
												{
													if (h[i].seq == rec.get("seq"))
													{
														hl = h[i];
														h.splice(i, 1);
														break;
													}
												}
												
												if (hl)
												{
													grid.store.removeAt(rowIndex);
												}
											},
											scope: this
										}
									]
								}
							],
							listeners: {
								cellclick: function(grid, td, cellIndex, record, rowIndex, e) {
									var me = this,
										rec = grid.store.getAt(rowIndex),
										hl,
										h = me._piobj._mc.highlight,
										i;
									
									if (cellIndex < 3 && cellIndex > 0)
									{
										for (i=0; i < h.length; i++)
										{
											if (h[i].seq == rec.get("seq"))
											{
												hl = h[i];
												break;
											}
										}
										
										if (hl)
										{
											me.make_new_option(hl);
										}
									}
								},
								scope: this
							}
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, {
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					this.init_f();
				}
			}
		});
		
		IG$.$d_hlconfig.superclass.initComponent.apply(this, arguments);
	}
});

IG$.$w_hl_config_item = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: {
		type: 'vbox',
		align: 'stretch'
	},
	
	closable: false,
	resizable:false,
	width: 450,
	height: 400,
	
	_confirm: function() {
		var me = this;
		me.commit_f();
		me.callback && me.callback.execute(me.hlobj);
		me.close();
	},
	
	init_f: function() {
		var me = this,
			_piobj = me._piobj,
			hlobj = me.hlobj,
			_mc = _piobj._mc,
			defaultstyle = _mc.defaultstyle,
			customstyle = _mc.customstyle,
			styles = [],
			dsitem = me.down("[name=dsitem]"),
			stylename = me.down("[name=stylename]"),
			i, appset,
			__global_cs = me.__global_cs;

		if (__global_cs)
		{
			for (i=0; i < __global_cs.length; i++)
			{
				styles.push({
					name: __global_cs[i].name,
					value: __global_cs[i].name
				});
			}
		}
				
		$.each([defaultstyle, customstyle], function(i, obj) {
			var i,
				st;
			
			if (!obj)
				return;
				
			for (i=0; i < obj.length; i++)
			{
				st = {
					name: obj[i].name,
					value: obj[i].name
				};
				
				styles.push(st);
			}
		});
		
		stylename.store.loadData(styles);
		
		appset = hlobj.appset || {};
		
		for (i in appset)
		{
			switch (i)
			{
			case "bg":
				me.down("[name=aset_1]").setValue(true);
				break;
			case "fs":
				me.down("[name=aset_2]").setValue(true);
				break;
			case "format":
				me.down("[name=aset_3]").setValue(true);
				break;
			case "tmpl":
				me.down("[name=aset_4]").setValue(true);
				break;
			}
		}
		
		me.dsitemuid = hlobj.uid;
		dsitem.setValue(hlobj.name);
		me.down("[name=delimiter]").setValue(hlobj.delimiter || ";");
		me.down("[name=operator]").setValue(hlobj.operator || "EQ");
		me.down("[name=stylename]").setValue(hlobj.stylename);
		me.down("[name=apprange]").setValue(hlobj.apprange || "CELL");
		me.down("[name=values]").setValue(hlobj.value_desc);
	},

	commit_f: function() {
		var me = this,
			hlobj = me.hlobj,
			dsitem = me.down("[name=dsitem]"),
			i, aset = {},
			vcode;
		
		$.each([{fname: "aset_1", code: "bg"}, {fname: "aset_2", code: "fs"}, {fname: "aset_3", code: "format"}, {fname: "aset_4", code: "tmpl"}], function(i, value) {
			if (me.down("[name=" + value.fname + "]").getValue() == true)
			{
				aset[value.code] = 1;
			}
		});	
		
		hlobj.appset = aset;
		
		hlobj.field = {
			uid: me.dsitemuid,
			name: dsitem.getValue()
		};
		hlobj.uid = me.dsitemuid;
		hlobj.itemname = dsitem.getValue();
		hlobj.name = hlobj.itemname;
		hlobj.delimiter = me.down("[name=delimiter]").getValue();
		hlobj.operator = me.down("[name=operator]").getValue();
		hlobj.stylename = me.down("[name=stylename]").getValue();
		hlobj.apprange = me.down("[name=apprange]").getValue();
		
		hlobj.values = [];
		vcode = me.down("[name=values]").getValue();
		hlobj.value_desc = vcode;
		
		if (vcode)
		{
			vcode = vcode.split(",");
			
			for (i=0; i < vcode.length; i++)
			{
				hlobj.values.push({
					code: vcode[i]
				});
			}
		}
	},
	
	cubeSelectedHandler: function() {
		var me = this,
			dlgitemsel = new IG$.metaSelectDlg({
				instance: me.instance,
				visibleItems: 'workspace;folder;metric;table;dataset;inlineview;measure;formulameasure;',
				tree_options: {
					cubebrowse: true,
					rootuid: me._piobj._mc.uid
				},
				callback: new IG$.callBackObj(me, me.rs_cubeSelectedHandler)
			});
		IG$.checkLogin(me, dlgitemsel);
	},
	
	rs_cubeSelectedHandler: function(item) {
		var me = this;
		
		me.dsitemuid = item.uid;
		me.down("[name=dsitem]").setValue(item.name);
	},
	
	initComponent : function() {
		var me = this;
	
		me.title = IRm$.r1('T_HL_OPT');
				 
		$s.apply(this, {
			padding: ig$.padding,
			
			items: [
				{
					xtype: "form",
					layout: "anchor",
					autoScroll: true,
					
					defaults: {
						anchor: "100%"
					},
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1("L_GENERAL_OPTION"),
							layout: "anchor",
							defaults: {
								anchor: "100%"
							},
							items: [
								{
									xtype: "fieldcontainer",
									layout: {
										type: "hbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "textfield",
											name: "dsitem",
											emptyText: IRm$.r1("M_SEL_ITEM"),
											readOnly: true,
											fieldLabel: IRm$.r1("B_NAME")
										},
										{
											xtype: "button",
											iconCls: "icon-toolbar-search",
											tooltip: IRm$.r1("B_SEARCH"),
											handler: function() {
												this.cubeSelectedHandler();
											},
											scope: this
										}
									   ]
								},
								{
									xtype: "combobox",
									fieldLabel: IRm$.r1("L_CONDITION"),
									name: "operator",
									
									valueField: 'value',
									displayField: 'name',
									editable: false,
									queryMode: "local",
									autoSelect: true,
									autoScroll: true,
									
									store: {
										xtype: "store",
										fields: [
											"name", "value"
										],
										data: [
											{name: IRm$.r1("L_F_EQ"), value: "EQ"},
											{name: IRm$.r1("L_F_LT"), value: "LT"},
											{name: IRm$.r1("L_F_LE"), value: "LTE"},
											{name: IRm$.r1("L_F_GT"), value: "GT"},
											{name: IRm$.r1("L_F_GE"), value: "GTE"},
											{name: IRm$.r1("L_F_BETWEEN"), value: "BTW"},
											{name: IRm$.r1("L_F_LIKE"), value: "LIKE"},
											{name: IRm$.r1("L_F_IN"), value: "IN"}
										]
									},
									listeners: {
										change: function(tobj) {
											var me = this,
												delimiter = me.down("[name=delimiter]"),
												gval = tobj.getValue();
											
											delimiter.setVisible(gval == "IN" || gval == "BTW");
										},
										scope: this
									}
								},
								{
									xtype: "fieldcontainer",
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "textarea",
											fieldLabel: IRm$.r1("B_VALUES"),
											name: "values"
										},
										{
											xtype: "textfield",
											hidden: true,
											fieldLabel: IRm$.r1("B_DELIMITER"),
											name: "delimiter"
										}
									]
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_STYLE_OPTION"),
							layout: "anchor",
							defaults: {
								anchor: "100%"
							},
							items: [
								{
									xtype: "combobox",
									fieldLabel: IRm$.r1("L_ST_NAME"),
									name: "stylename",
									
									valueField: 'value',
									displayField: 'name',
									editable: false,
									queryMode: "local",
									autoSelect: true,
									autoScroll: true,
									
									store: {
										xtype: "store",
										fields: [
											"name", "value"
										]
									}
								},
								{
									xtype: "combobox",
									name: "apprange",
									fieldLabel: IRm$.r1("L_HL_RANGE"),
									
									valueField: 'value',
									displayField: 'name',
									editable: false,
									queryMode: "local",
									autoSelect: true,
									autoScroll: true,
									
									store: {
										xtype: "store",
										fields: [
											"name", "value"
										],
										data: [
											{name: IRm$.r1("L_HL_CELL"), value: "CELL"},
											{name: IRm$.r1("L_HL_ROW"), value: "ROW"},
											{name: IRm$.r1("L_HL_COL"), value: "COL"}
										]
									}
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_APPL_R"),
							layout: "anchor",
							items: [
								{
									xtype: "checkbox",
									name: "aset_1",
									boxLabel: IRm$.r1("L_BG_COL")
								},
								{
									xtype: "checkbox",
									name: "aset_2",
									boxLabel: IRm$.r1("L_FONT_ST")
								},
								{
									xtype: "checkbox",
									name: "aset_3",
									boxLabel: IRm$.r1("L_F_STR")
								},
								{
									xtype: "checkbox",
									name: "aset_4",
									boxLabel: IRm$.r1("L_F_TMPL")
								}
							]
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, {
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					this.init_f();
				}
			}
		});
		
		IG$.$w_hl_config_item.superclass.initComponent.apply(this, arguments);
	}
});