
/***********************************************************************
 * AppPageControl: TextArea 
 */
 IG$.ctrlTextArea = IG$.extend(IG$.ctrlBase, {
	type: "textarea",
	initComponent: function() {
		var me = this;
			
		me.p.push(
			{name: "fieldlabel", type: "property", datatype: "string"},
			{name: "flexHeight", type: "property", datatype: "number", value: 0},
			{name: "minHeight", type: "property", datatype: "number", value: 0},
			{name: "htmltext", type: "property", datatype: "string"},
			{name: "text", type: "property", datatype: "string"}
		);
	
		me.superclass.prototype.initComponent.call(me);
	},
	
	updateProperty: function(kname, value) {
		var me = this,
			cmp$ = me.cmp$;
		
		switch (kname)
		{
		case "htmltext":
		case "text":
			me.mp$.value = value;
			break;
		}
	},

	initDrawing: function () {
		var me = this,
			actionlist = me.ctrl.actionlist,
			property = me.property,
			owner = me.ctrl.owner,
			cmp$,
			lbl$,
			fid = me._get_id();

		// cmp$ = me.cmp$ = $("<textarea class='form-control' id='" + fid + "'/>").appendTo(me.el$);
		// lbl$ = me.lbl$ = $("<label class='form-label' for='" + fid + "'>" + (me.property.fieldlabel || "") + "</label>"); // .appendTo(me.el$);
		me.el$.addClass("form-outline");
		me.tl$ && me.tl$.hide();
		me.mp$ = $("<label class='mdc-text-field mdc-text-field--outlined mdc-text-field--textarea mdc-text-field--no-label igc-md-ctrl igc-form-control igc-md-ctrl-textarea' type='text'>" + me.createNotch(me.property.fieldlabel, fid) + "<textarea class='mdc-text-field__input' aria-label='Label'></textarea><span class='mdc-line-ripple'></span></label>")
			.appendTo(me.el$)[0];
		me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$);
		me.superclass.prototype.initDrawing.call(me);
	},
		
	invalidate: function () {
	},
	
	commit: function() {
		var me = this;
		me.property.text = me.mp$.value;
	}
});

IG$.controls.textarea = new IG$.ctrlTextArea({}, null);